// The IEEE OUI registry python mac80211._oui_db() loads from data/oui.tsv.gz, compiled in
// (oui_table.cpp is generated by gen_oui_table.py; no runtime file, no zlib).
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>

namespace si::rx::wifi::detail {

// Vendor name (UTF-8, NUL-terminated, static storage) of an exact registry key: 6 (MA-L),
// 7 (MA-M) or 9 (MA-S) upper-case hex digits; nullptr when the key is not registered.
const char* oui_registry(const std::string& hex_upper);
size_t oui_registry_size();

}  // namespace si::rx::wifi::detail
